{"type":"object","properties":{
            "title":{"type":"string","description":"Ticket title"},
            "description":{"type":"string","description":"Detailed description of the incident"},
            "priority":{"type":"string","description":"low, medium, high, urgent","default":"medium"},
            "minion":{"type":"string","description":"Affected machine/minion","default":""},
            "service":{"type":"string","description":"Affected service: odoo, caddy, postgres, postfix, dovecot, garage, bifrost, etc.","default":""}
        },"required":["title","description"]}

async def execute(title, description, priority="medium", minion="", service=""):
    """Create a helpdesk ticket with infrastructure context."""
    priority_map = {"low": "0", "medium": "1", "high": "2", "urgent": "3"}

    ticket_vals = {
        "name": title,
        "description": description,
        "priority": priority_map.get(priority, "1"),
    }

    # Add infrastructure context to description
    context_lines = []
    if minion:
        context_lines.append(f"Minion: {minion}")
    if service:
        context_lines.append(f"Service: {service}")
    if context_lines:
        ticket_vals["description"] = (
            description + "\n\n--- Infrastructure Context ---\n" +
            "\n".join(context_lines)
        )

    ticket = env["helpdesk.ticket"].create(ticket_vals)
    return f"Helpdesk ticket created: {ticket.name} (ID: {ticket.id})"

